  httpBasicAuth: CredentialReference;
  httpHeaderAuth: CredentialReference;
  jwtAuth: CredentialReference;
}

interface WebhookV22NodeBase {
  type: 'n8n-nodes-base.webhook';
  version: 2.2;
}

export type WebhookV22ParamsNode = WebhookV22NodeBase & {
  config: NodeConfig<WebhookV22Params> & { credentials?: WebhookV22Credentials };
  output?: Items<WebhookV22Output>;
